INSERT INTO dump_descriptions (base_key, description) VALUES ('ennbiomeschrompv7.1toggleable', 'Adds a Mod Hub toggle between the Schmorp and vanilla biome settings, with custom cave layouts and reactive-terrain effects.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('u39更多敌人简化模型', 'Replaces skeletal meshes for a broad range of enemies with simplified models, including spiders, jellyfish, leeches, plants, woodlice, and plague creatures.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('dea_a03', 'Adds custom enemy variants, including Glasher, Spitter and Shooter types, Mactera and Bomber variants, Woodlouse Shooter, Drone Breeder, Sprout, and Stabber Vine.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('yomama', 'Adds custom enemy variants and test dummies, including spider tanks with health, speed, stun, temperature, and other aura effects, plus movement-speed and shield-control dummies.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
